const item = $input.item;
const f = item.json || {};
const CONFIG = {
  reviewer_email: 'pakistaniyouth9304598@gmail.com',
  google_sheet_id: '1O0WCZOAmSwbNRLswH4ukjE6CnRnBIiXPrUjVHmwawN8',
  sheet_name: 'Candidates',
  drive_folder_id: 'root',
  role: 'Machine Learning Engineer',
  minimum_relevant_experience_years: 3,
  criteria_version: 'ML-ENG-v1.0',
  ai_model: 'models/gemini-2.5-flash'
};

const clean = (v) => String(v ?? '').trim();
const experience = Number(f['Relevant Experience (Years)']);
const resumeMeta = f['Resume PDF'] || {};
const binaryResume = item.binary?.Resume_PDF;
const errors = [];
if (!clean(f['Full Name'])) errors.push('Full name is required');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(clean(f.Email))) errors.push('A valid email is required');
if (!clean(f['Degree / Equivalent Learning'])) errors.push('Degree or equivalent learning is required');
if (!Number.isFinite(experience) || experience < 0) errors.push('Relevant experience must be a non-negative number');
if (!clean(f['Claimed Skills'])) errors.push('Claimed skills are required');
if (clean(f['Classical ML Project Evidence']).length < 40) errors.push('Classical ML project evidence needs more detail');
if (clean(f['Deep Learning Project Evidence']).length < 40) errors.push('Deep learning project evidence needs more detail');
if (!clean(f.Availability)) errors.push('Availability is required');
if (clean(f.Consent).toLowerCase() !== 'yes') errors.push('Consent is required');
if (!binaryResume) errors.push('Resume PDF is required');
const mime = clean(binaryResume?.mimeType || resumeMeta.mimetype).toLowerCase();
const filename = clean(binaryResume?.fileName || resumeMeta.filename);
if (binaryResume && mime && mime !== 'application/pdf' && !filename.toLowerCase().endsWith('.pdf')) errors.push('Resume must be a PDF');
const bytes = Number(resumeMeta.size || 0);
if (bytes > 5 * 1024 * 1024) errors.push('Resume must be 5 MB or smaller');

const candidateId = 'ML-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8).toUpperCase();
return {
  json: {
    config: CONFIG,
    candidate_id: candidateId,
    submitted_at: new Date().toISOString(),
    full_name: clean(f['Full Name']),
    email: clean(f.Email).toLowerCase(),
    phone: clean(f.Phone),
    role: CONFIG.role,
    degree: clean(f['Degree / Equivalent Learning']),
    claimed_experience_years: Number.isFinite(experience) ? experience : '',
    claimed_skills: clean(f['Claimed Skills']),
    ml_project_summary: clean(f['Classical ML Project Evidence']),
    dl_project_summary: clean(f['Deep Learning Project Evidence']),
    availability: clean(f.Availability),
    linkedin_url: clean(f['LinkedIn URL']),
    github_url: clean(f['GitHub / Portfolio URL']),
    consent: clean(f.Consent),
    cv_file_name: filename,
    is_valid: errors.length === 0,
    validation_errors: errors.join('; '),
    status: errors.length === 0 ? 'RECEIVED' : 'INCOMPLETE'
  },
  binary: item.binary || {}
};

const a = $('01 - Configure and Validate').item.json;
const driveInput = $json || {};
const drive = driveInput;
const driveError = drive.error ? String(drive.error.message || drive.error) : '';
const fileId = drive.id || '';
const cvUrl = drive.webViewLink || (fileId ? 'https://drive.google.com/file/d/' + fileId + '/view' : '');
return { json: {
  candidate_id: a.candidate_id, submitted_at: a.submitted_at, full_name: a.full_name,
  email: a.email, phone: a.phone, role: a.role, degree: a.degree,
  claimed_experience_years: a.claimed_experience_years, claimed_skills: a.claimed_skills,
  ml_project_summary: a.ml_project_summary, dl_project_summary: a.dl_project_summary,
  availability: a.availability, linkedin_url: a.linkedin_url, github_url: a.github_url,
  consent: a.consent, cv_file_name: a.cv_file_name, cv_url: cvUrl,
  status: 'RECEIVED', validation_errors: '', criteria_version: a.config.criteria_version,
  ai_model: a.config.ai_model, error_message: driveError ? 'CV upload failed: ' + driveError : ''
} };

const source = $json || {};
const extractionError = source.error ? String(source.error.message || source.error) : '';
let text = String(source.text || source.data || '');
text = text.replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[EMAIL REDACTED]');
text = text.replace(/(?:\+?\d[\d\s().-]{7,}\d)/g, '[PHONE REDACTED]');
text = text.slice(0, 30000);
return { json: { resume_text: text, extraction_error: extractionError || (!text ? 'No text extracted from PDF' : '') } };

const a = $('01 - Configure and Validate').item.json;
return { json: {
  candidate_id: a.candidate_id, submitted_at: a.submitted_at, full_name: a.full_name,
  email: a.email, phone: a.phone, role: a.role, degree: a.degree,
  claimed_experience_years: a.claimed_experience_years, claimed_skills: a.claimed_skills,
  ml_project_summary: a.ml_project_summary, dl_project_summary: a.dl_project_summary,
  availability: a.availability, linkedin_url: a.linkedin_url, github_url: a.github_url,
  consent: a.consent, cv_file_name: a.cv_file_name, status: 'INCOMPLETE',
  validation_errors: a.validation_errors, criteria_version: a.config.criteria_version,
  ai_model: a.config.ai_model, notification_status: 'CORRECTION_REQUIRED'
} };

const app = $('01 - Configure and Validate').item.json;
const merged = $('06 - Merge Stored Data and Resume Text').item.json;
const incoming = $json || {};
const candidateAi = incoming.output && typeof incoming.output === 'object' ? incoming.output : incoming;
const aiFailed = Boolean(incoming.error) || !candidateAi || !Array.isArray(candidateAi.normalized_skills);
const ai = aiFailed ? {} : candidateAi;

const array = (v) => Array.isArray(v) ? v.map(String) : [];
const lower = (v) => String(v ?? '').toLowerCase();
const skillText = lower(array(ai.normalized_skills).join(' ') + ' ' + app.claimed_skills);
const hasAny = (aliases) => aliases.some((x) => skillText.includes(x));
const checks = [
  ['Python', ['python']],
  ['NumPy', ['numpy']],
  ['pandas', ['pandas']],
  ['scikit-learn', ['scikit-learn', 'sklearn']],
  ['SQL', ['sql', 'postgresql', 'mysql']],
  ['Git', ['git', 'github', 'gitlab']],
  ['Preprocessing / feature engineering', ['preprocessing', 'feature engineering', 'feature selection']],
  ['Model evaluation', ['model evaluation', 'cross-validation', 'cross validation', 'f1', 'roc', 'precision', 'recall']]
];
const coreMatches = checks.filter(([, aliases]) => hasAny(aliases)).map(([name]) => name);
const coreGaps = checks.filter(([, aliases]) => !hasAny(aliases)).map(([name]) => name);
const coreScore = 25 * coreMatches.length / checks.length;

const ml = ai.ml_project_evidence || {};
const dl = ai.dl_project_evidence || {};
const mlKeys = ['problem','dataset','preprocessing','algorithm','evaluation','result','contribution','repository_or_deployment'];
const dlKeys = ['problem','dataset','framework','architecture','training_process','evaluation','result','error_analysis','contribution','repository_or_demo'];
const mlScore = aiFailed ? 0 : 20 * mlKeys.filter((k) => ml[k] === true).length / mlKeys.length;
const dlScore = aiFailed ? 0 : 20 * dlKeys.filter((k) => dl[k] === true).length / dlKeys.length;

const extractedYears = Number(ai.relevant_experience_years);
const claimedYears = Number(app.claimed_experience_years);
const relevantYears = Number.isFinite(extractedYears) ? extractedYears : (Number.isFinite(claimedYears) ? claimedYears : 0);
const experienceScore = 15 * Math.min(Math.max(relevantYears, 0) / app.config.minimum_relevant_experience_years, 1);

const productionText = lower(array(ai.production_evidence).join(' ') + ' ' + skillText);
const prodChecks = [
  ['API serving', ['fastapi','flask','model api']],
  ['Docker', ['docker','container']],
  ['Cloud', ['aws','azure','gcp','google cloud']],
  ['Experiment tracking', ['mlflow','weights & biases','wandb','experiment tracking']],
  ['CI/CD', ['ci/cd','continuous integration','github actions']],
  ['Monitoring', ['model monitoring','drift','prometheus','grafana']]
];
const prodMatches = prodChecks.filter(([, aliases]) => aliases.some((x) => productionText.includes(x))).map(([name]) => name);
const productionScore = 15 * prodMatches.length / prodChecks.length;
const degreeText = lower(app.degree);
const degreeRelevant = ai.degree_relevant === true || /(computer science|software engineering|data science|artificial intelligence|machine learning|mathematics|statistics|engineering|equivalent)/.test(degreeText);
const educationScore = degreeRelevant ? 5 : 0;

const dlFramework = hasAny(['pytorch','tensorflow','keras']);
const mandatoryGaps = [];
if (relevantYears < app.config.minimum_relevant_experience_years) mandatoryGaps.push('Less than 3 years of relevant ML experience');
if (aiFailed || ml.present !== true) mandatoryGaps.push('No verified end-to-end classical ML project');
if (aiFailed || dl.present !== true) mandatoryGaps.push('No verified substantial deep-learning project');
if (!hasAny(['python'])) mandatoryGaps.push('Python not evidenced');
if (!hasAny(['scikit-learn','sklearn'])) mandatoryGaps.push('scikit-learn not evidenced');
if (!dlFramework) mandatoryGaps.push('PyTorch or TensorFlow/Keras not evidenced');
if (aiFailed) mandatoryGaps.push('AI extraction unavailable — manual CV review required');

const score = Math.round((coreScore + mlScore + dlScore + experienceScore + productionScore + educationScore) * 10) / 10;
let recommendation = 'RECOMMEND_REJECT';
if (aiFailed) recommendation = 'NEEDS_CLOSER_REVIEW';
else if (score >= 80 && mandatoryGaps.length === 0) recommendation = 'RECOMMEND_SHORTLIST';
else if (score >= 60 || Number(ai.confidence || 0) < 0.65) recommendation = 'NEEDS_CLOSER_REVIEW';
const reviewPriority = recommendation === 'RECOMMEND_SHORTLIST' ? 'FAST_SHORTLIST_REVIEW' : (recommendation === 'RECOMMEND_REJECT' ? 'FAST_REJECTION_REVIEW' : 'DEEP_REVIEW');
const breakdown = {
  core_ml_skills: Math.round(coreScore * 10) / 10,
  classical_ml_project: Math.round(mlScore * 10) / 10,
  deep_learning_project: Math.round(dlScore * 10) / 10,
  relevant_experience: Math.round(experienceScore * 10) / 10,
  production_mlops: Math.round(productionScore * 10) / 10,
  education_equivalent: educationScore
};
const evidence = array(ai.evidence_quotes);
const risks = array(ai.risk_flags);
const aiReason = aiFailed
  ? 'AI parsing failed; the workflow safely routed this application for manual review.'
  : [String(ai.summary || ''), risks.length ? 'Risk flags: ' + risks.join('; ') : ''].filter(Boolean).join(' ');
const cvUrl = merged.cv_url || '';
const reviewMessage = [
  'AUTHORIZED HUMAN REVIEW — MACHINE LEARNING ENGINEER',
  '',
  'Candidate ID: ' + app.candidate_id,
  'Candidate: ' + app.full_name + ' <' + app.email + '>',
  'Relevant experience assessed: ' + relevantYears + ' years',
  'Availability: ' + app.availability,
  'Degree / equivalent learning: ' + app.degree,
  'GitHub / portfolio: ' + (app.github_url || 'Not supplied'),
  'LinkedIn: ' + (app.linkedin_url || 'Not supplied'),
  'CV: ' + (cvUrl || 'Drive upload unavailable — inspect the original execution binary'),
  '',
  'Advisory score: ' + score + '/100',
  'AI recommendation: ' + recommendation,
  'Review priority: ' + reviewPriority,
  'Breakdown: ' + JSON.stringify(breakdown),
  'Core matches: ' + (coreMatches.join(', ') || 'None'),
  'Core gaps: ' + (coreGaps.join(', ') || 'None'),
  'Production evidence: ' + (prodMatches.join(', ') || 'None'),
  'Mandatory gaps: ' + (mandatoryGaps.join('; ') || 'None'),
  'Evidence: ' + (evidence.join('; ') || 'No short evidence returned'),
  'Assessment note: ' + aiReason,
  '',
  'AI is advisory only. Check the CV and evidence, then choose SHORTLIST or REJECT below.'
].join('\n');

return { json: {
  candidate_id: app.candidate_id, submitted_at: app.submitted_at, full_name: app.full_name,
  email: app.email, phone: app.phone, role: app.role, degree: app.degree,
  claimed_experience_years: app.claimed_experience_years, claimed_skills: app.claimed_skills,
  ml_project_summary: app.ml_project_summary, dl_project_summary: app.dl_project_summary,
  availability: app.availability, linkedin_url: app.linkedin_url, github_url: app.github_url,
  consent: app.consent, cv_file_name: app.cv_file_name, cv_url: cvUrl,
  extraction_error: merged.extraction_error || '', status: 'PENDING_HUMAN_REVIEW', validation_errors: '',
  normalized_skills: array(ai.normalized_skills).join(', '), core_skill_matches: coreMatches.join(', '),
  core_skill_gaps: coreGaps.join(', '), mandatory_gaps: mandatoryGaps.join('; '),
  score, score_breakdown: JSON.stringify(breakdown), recommendation, ai_reason: aiReason,
  ai_confidence: Number(ai.confidence || 0), criteria_version: app.config.criteria_version,
  ai_model: app.config.ai_model, review_priority: reviewPriority, review_message: reviewMessage,
  human_decision: 'PENDING', reviewer_email: app.config.reviewer_email, notification_status: 'PENDING',
  error_message: merged.error_message || (incoming.error ? String(incoming.error.message || incoming.error) : ''),
  candidate_email: app.email, candidate_full_name: app.full_name, config: app.config
} };

const assessment = $('08 - Deterministic Scoring and Review Packet').item.json;
const approved = $json?.data?.approved === true;
const decision = approved ? 'SHORTLISTED' : 'REJECTED';
return { json: {
  ...assessment,
  status: decision,
  human_decision: decision,
  reviewer_email: assessment.config.reviewer_email,
  reviewed_at: new Date().toISOString(),
  notification_status: 'PENDING',
  notified_at: ''
} };

const decision = $('11 - Prepare Human Decision').item.json;
const failed = Boolean($json?.error);
const successLabel = 'SHORTLIST_EMAIL_SENT';
const failLabel = 'SHORTLIST_EMAIL_FAILED';
return { json: {
  ...decision,
  notification_status: failed ? failLabel : successLabel,
  notified_at: failed ? '' : new Date().toISOString(),
  error_message: failed ? String($json.error.message || $json.error) : decision.error_message
} };

const decision = $('11 - Prepare Human Decision').item.json;
const failed = Boolean($json?.error);
const successLabel = 'REJECTION_EMAIL_SENT';
const failLabel = 'REJECTION_EMAIL_FAILED';
return { json: {
  ...decision,
  notification_status: failed ? failLabel : successLabel,
  notified_at: failed ? '' : new Date().toISOString(),
  error_message: failed ? String($json.error.message || $json.error) : decision.error_message
} };
